Here's how to read a JSON file in Node.js:

```javascript
const fs = require('fs');

// Method 1: Synchronous (blocking) - simplest
const data = JSON.parse(fs.readFileSync('file.json', 'utf8'));
console.log(data);

// Method 2: Asynchronous (non-blocking) - recommended for production
fs.readFile('file.json', 'utf8', (err, jsonString) => {
  if (err) {
    console.error('Error reading file:', err);
    return;
  }
  try {
    const data = JSON.parse(jsonString);
    console.log(data);
  } catch (parseErr) {
    console.error('Error parsing JSON:', parseErr);
  }
});

// Method 3: Using require() - caches the file, only works for .json extension
const data = require('./file.json');
console.log(data);

// Method 4: Using promises (Node 14+)
const fsPromises = require('fs').promises;
async function readJson() {
  try {
    const jsonString = await fsPromises.readFile('file.json', 'utf8');
    const data = JSON.parse(jsonString);
    console.log(data);
  } catch (err) {
    console.error('Error:', err);
  }
}
readJson();
```

**Key points:**
- Always use `JSON.parse()` to convert the string to a JavaScript object
- Handle errors with try/catch or error callbacks
- For large files, use the asynchronous methods to avoid blocking the event loop
- `require()` is convenient but caches the result and only works with `.json` files

For most applications, **Method 4 (async/await with promises)** is the cleanest and most modern approach.

 Here's how to read a JSON file in Node.js:

```javascript
// Method 1: Using require (synchronous, simplest)
const fs = require('fs');
const data = JSON.parse(fs.readFileSync('data.json', 'utf8'));
console.log(data);

// Method 2: Using fs.promises (async/await, recommended)
const fs = require('fs').promises;

async function readJson() {
  const data = await fs.readFile('data.json', 'utf8');
  return JSON.parse(data);
}

readJson().then(console.log);

// Method 3: Using require directly (only for .json files)
const data = require('./data.json');
console.log(data);
```

**Key points:**
- Method 1 is synchronous and blocks the event loop — fine for small config files at startup
- Method 2 is asynchronous and non-blocking — best for production code
- Method 3 works only for `.json` extension and caches the result

**Example `data.json`:**
```json
{
  "name": "John",
  "age": 30,
  "city": "New York"
}
```

**Error handling (recommended for production):**
```javascript
const fs = require('fs').promises;

async function readJsonSafe(filePath) {
  try {
    const raw = await fs.readFile(filePath, 'utf8');
    return JSON.parse(raw);
  } catch (err) {
    console.error('Failed to read JSON:', err.message);
    return null;
  }
}
```

For most cases, use **Method 2** with async/await — it's clean, non-blocking, and handles large files well.

