 Here's how to read a JSON file in Node.js:

## Method 1: Using `require()` (synchronous, simplest)

```javascript
// For JSON files, require() automatically parses them
const data = require('./data.json');
console.log(data);
```

## Method 2: Using `fs.readFileSync()` (synchronous)

```javascript
const fs = require('fs');

try {
  const rawData = fs.readFileSync('./data.json', 'utf8');
  const data = JSON.parse(rawData);
  console.log(data);
} catch (error) {
  console.error('Error reading file:', error.message);
}
```

## Method 3: Using `fs.promises.readFile()` (asynchronous, recommended)

```javascript
const fs = require('fs').promises;

async function readJsonFile() {
  try {
    const rawData = await fs.readFile('./data.json', 'utf8');
    const data = JSON.parse(rawData);
    console.log(data);
  } catch (error) {
    console.error('Error reading file:', error.message);
  }
}

readJsonFile();
```

## Method 4: Using `fs.readFile()` with callbacks (asynchronous)

```javascript
const fs = require('fs');

fs.readFile('./data.json', 'utf8', (err, rawData) => {
  if (err) {
    console.error('Error reading file:', err.message);
    return;
  }

  try {
    const data = JSON.parse(rawData);
    console.log(data);
  } catch (parseError) {
    console.error('Invalid JSON:', parseError.message);
  }
});
```

## Complete example with error handling

```javascript
const fs = require('fs').promises;

async function readJsonFile(filePath) {
  try {
    const rawData = await fs.readFile(filePath, 'utf8');
    return JSON.parse(rawData);
  } catch (error) {
    if (error.code === 'ENOENT') {
      throw new Error(`File not found: ${filePath}`);
    }
    if (error instanceof SyntaxError) {
      throw new Error(`Invalid JSON in ${filePath}: ${error.message}`);
    }
    throw error;
  }
}

// Usage
(async () => {
  try {
    const data = await readJsonFile('./config.json');
    console.log('Data loaded:', data);
  } catch (error) {
    console.error('Failed:', error.message);
  }
})();
```

## Which to use?

- **`require()`** – simplest, but caches the result (won't re-read if file changes) and only works with `.json` extension
- **`fs.readFileSync()`** – good for one-time reads at startup
- **`fs.promises.readFile()`** – **recommended** for modern async/await code
- **Callback version** – use only if you're stuck with callbacks

For most applications, use **Method 3** with async/await – it's clean, non-blocking, and handles errors well.

A diferença principal é o **escopo** e a **possibilidade de reatribuição**.  

- **`var`** tem escopo de função (ou global) e pode ser reatribuída e redeclarada.  
- **`let`** tem escopo de bloco (ex: dentro de `{}`), pode ser reatribuída, mas **não** redeclarada no mesmo escopo.  
- **`const`** também tem escopo de bloco, mas **não pode ser reatribuída** após a inicialização (obrigatória).  

Na prática, use `const` por padrão, `let` quando precisar reatribuir, e evite `var` em código moderno.

---

**Exemplo rápido:**

```javascript
var a = 1;
let b = 2;
const c = 3;

// var: redeclarar funciona (não recomendado)
var a = 10;

// let: reatribuir funciona
b = 20;

// const: reatribuir dá erro
// c = 30; // TypeError

// Escopo de bloco
if (true) {
  var x = 'var'; // vaza para fora do bloco
  let y = 'let'; // só existe dentro do bloco
  const z = 'const'; // só existe dentro do bloco
}
console.log(x); // 'var'
// console.log(y); // ReferenceError
// console.log(z); // ReferenceError
```
